e-height:1.5}.wallet-alert.is-visible{display:block}.wallet-alert.is-error{background:#be2a3c14;color:#c02c43}.wallet-alert.is-success{background:#0e693712;color:#16824a}.wallet-upload-help{font-size:11px;color:var(--wm);line-height:1.6;margin:12px 0 0}html[data-theme="dark"] .wallet-page{--wi:var(--text-color,#f0eaf8);--wm:#a9a2b7;--wl:#ffffff1a;--ws:var(--card-bg,#171522);--wb:#c8a9f4}html[data-theme="dark"] .wallet-address-card{background:#ffffff06}html[data-theme="dark"] .wallet-address-value{background:#0002}html[data-theme="dark"] .wallet-count,html[data-theme="dark"] .wallet-btn-soft{color:#c8a9f4!important}html[data-theme="dark"] .wallet-security{background:#0e69371a;color:var(--wm)}html[data-theme="dark"] .wallet-alert.is-error{background:#be2a3c26;color:#ff9aa6}html[data-theme="dark"] .wallet-alert.is-success{background:#0e693726;color:#7ee0ad}@media(max-width:900px){.wallet-layout{grid-template-columns:minmax(0,1fr)}.wallet-right-column{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.wallet-right-column .wallet-panel{margin-bottom:0}}@media(max-width:600px){.wallet-page{padding:17px 10px 25px}.wallet-hero{padding:22px 18px;border-radius:17px}.wallet-layout{gap:12px}.wallet-panel{padding:16px;border-radius:15px;margin-bottom:12px}.wallet-right-column{grid-template-columns:1fr;gap:12px}.wallet-address-card{padding:12px}.wallet-address-value{font-size:11px}.wallet-btn{min-height:42px}.wallet-panel-head{margin-bottom:13px}}@media(prefers-reduced-motion:reduce){.wallet-btn{transition:none}}
